                    <input type="text" required value={address} onChange={e=>setAddress(e.target.value)} placeholder="Dirección de estudio o calle (ej. Calle del Pez 28, Local B)" className="w-full bg-[#0a0a0a] border border-zinc-800 rounded-xl px-4 py-3.5 text-white focus:outline-none focus:border-violet-500 transition-colors mb-4" />
                    <div className="grid grid-cols-2 gap-4">
                      <input type="text" required value={city} onChange={e=>setCity(e.target.value)} placeholder="Ciudad / Localidad (ej. Madrid)" className="w-full bg-[#0a0a0a] border border-zinc-800 rounded-xl px-4 py-3.5 text-white focus:outline-none focus:border-violet-500 transition-colors" />
                      <input type="text" required value={postalCode} onChange={e=>setPostalCode(e.target.value)} placeholder="Código Postal (ej. 28004)" className="w-full bg-[#0a0a0a] border border-zinc-800 rounded-xl px-4 py-3.5 text-white focus:outline-none focus:border-violet-500 transition-colors" />
                    </div>
                  </div>
                </motion.div>
              )}
            </AnimatePresence>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
              <div>
                <label className="flex items-center justify-between text-sm font-medium text-white mb-2">
                  Contraseña segura
                  {password.length > 0 && <span className="text-[10px] text-emerald-400 font-bold">MEDIA</span>}
                </label>
                <div className="relative">
                  <input type={showPassword ? "text" : "password"} required value={password} onChange={e=>setPassword(e.target.value)} placeholder="••••••••••••" className="w-full bg-[#0a0a0a] border border-zinc-800 rounded-xl px-4 py-3.5 text-white focus:outline-none focus:border-violet-500 transition-colors" />
                  <button type="button" onClick={() => setShowPassword(!showPassword)} className="absolute right-4 top-1/2 -translate-y-1/2 text-zinc-500 hover:text-zinc-300">
                    {showPassword ? <EyeOff className="w-5 h-5"/> : <Eye className="w-5 h-5"/>}
                  </button>
                </div>
              </div>
              <div>
                <label className="flex items-center justify-between text-sm font-medium text-white mb-2">
                  Confirmar contraseña
                  {confirmPassword.length > 0 && confirmPassword === password && <span className="text-[10px] text-emerald-400 font-bold">COINCIDE</span>}
                </label>
                <div className="relative">
                  <input type={showPassword ? "text" : "password"} required value={confirmPassword} onChange={e=>setConfirmPassword(e.target.value)} placeholder="••••••••••••" className="w-full bg-[#0a0a0a] border border-zinc-800 rounded-xl px-4 py-3.5 text-white focus:outline-none focus:border-violet-500 transition-colors" />
                </div>
              </div>
            </div>

            {errorMsg && (
              <div className="p-4 bg-red-900/30 border border-red-500/50 rounded-xl text-red-400 text-sm">
                {errorMsg}
              </div>
            )}

            <div className="flex items-start gap-3 mt-6">
              <input type="checkbox" id="terms" checked={termsAccepted} onChange={(e) => setTermsAccepted(e.target.checked)} className="mt-1 w-5 h-5 rounded border-zinc-700 bg-zinc-900 text-violet-600 focus:ring-violet-500 focus:ring-offset-zinc-900" />
              <label htmlFor="terms" className="text-sm text-zinc-400">
                Acepto las <Link to="/legal/privacy" className="text-white hover:underline font-medium">Políticas de Privacidad</Link> y los <Link to="/legal/terms" className="text-white hover:underline font-medium">Términos y Condiciones</Link> de Tattoo Hub.
              </label>
            </div>

            <button disabled={loading} type="submit" className="w-full mt-8 bg-violet-600 hover:bg-violet-500 disabled:opacity-50 disabled:cursor-not-allowed text-white py-4 rounded-xl font-bold text-lg transition-all shadow-[0_0_20px_rgba(124,58,237,0.3)]">
              {loading ? 'Creando cuenta...' : 'Crear mi Cuenta - Empezar Ahora ?'}
            </button>

            <p className="text-center text-sm text-zinc-500 mt-6">
              ¿Ya tienes cuenta en Tattoo Hub? <Link to="/login" className="text-white font-medium hover:underline">Iniciar Sesión</Link>
            </p>
          </form>
        </div>

        {/* Trust Badges */}
        <div className="grid grid-cols-1 md:grid-cols-3 gap-6 mt-16 pb-20">
          <div className="bg-[#0f0f0f] border border-zinc-800/80 rounded-2xl p-6 flex items-start gap-4">
            <ShieldCheck className="w-6 h-6 text-emerald-400 shrink-0" />
            <div>
              <h4 className="text-white font-bold mb-1">Taller Libre de Comisiones</h4>
              <p className="text-zinc-500 text-xs leading-relaxed">El 100% de lo pactado por tus piezas es para ti. No intermediamos en el cobro de tu arte en camilla.</p>
            </div>
          </div>
          <div className="bg-[#0f0f0f] border border-zinc-800/80 rounded-2xl p-6 flex items-start gap-4">
            <Sparkles className="w-6 h-6 text-violet-400 shrink-0" />
            <div>
              <h4 className="text-white font-bold mb-1">Privacidad & Resguardo</h4>
              <p className="text-zinc-500 text-xs leading-relaxed">Tus bocetos, stencils y flashes no son utilizados para alimentar motores generativos de IA.</p>
            </div>
          </div>
          <div className="bg-[#0f0f0f] border border-zinc-800/80 rounded-2xl p-6 flex items-start gap-4">
            <Heart className="w-6 h-6 text-pink-400 shrink-0" />
            <div>
              <h4 className="text-white font-bold mb-1">Cultura Independiente</h4>
              <p className="text-zinc-500 text-xs leading-relaxed">Diseñado exclusivamente por y para la comunidad del tatuaje. Conectando tinta real con piel de verdad.</p>
            </div>
          </div>
        </div>
      </main>
    </div>
  );
};

